+/// Montgomery inverse. For Montgomery limbs `a = xR` this is `x^-1 R`.
+#[inline]
+fn invert_canonical(a: [u64; 4]) -> [u64; 4] {
+    // Invariants: u * s + v * r = n, a * s = v * 2^k and
+    // a * r = -u * 2^k (mod n). While u, v >= 1 this keeps r, s <= n.
+    let mut u = MODULUS;
+    let mut v = a;
+    let mut r = [0; 4];
+    let mut s = [1, 0, 0, 0];
+    let mut k = strip_twos(&mut v, &mut r);
