+    // u = n is never one; only the value updated in a step can become one.
+    if !is_one_limbs(v) {
+        loop {
+            let (difference, borrow) = sub_limbs(u, v);
+            if borrow == 0 {
+                u = difference;
+                r = add_limbs(r, s).0;
+                k += strip_twos(&mut u, &mut s);
+                if is_one_limbs(u) {
+                    break;
+                }
