+/// Removes all factors of two from `u`, multiplying `x` by
+/// the same power of two, and returns the number of bits removed.
+#[inline(always)]
+fn strip_twos(u: &mut [u64; 4], x: &mut [u64; 4]) -> u32 {
+    let mut removed = 0;
+    while u[0] & 1 == 0 {
+        let shift = u[0].trailing_zeros().min(63);
+        *u = shr_limbs(*u, shift);
+        *x = shl_limbs(*x, shift);
