+#[inline(always)]
+fn pow2_mod(exponent: u32) -> [u64; 4] {
+    if exponent == 256 {
+        return Scalar::ONE.limbs;
+    }
+    let mut limbs = [0; 4];
+    limbs[(exponent / 64) as usize] = 1u64 << (exponent % 64);
+    limbs
+}

